603	@@ -0,0 +1,83 @@
604	+"use client";
605	+
606	+import { ChevronLeft, ChevronRight } from "lucide-react";
607	+
608	+export type PageInfo = {
609	+  page: number;
610	+  limit: number;
611	+  total: number;
612	+};
613	+
614	+export type PaginationControlsProps = {
615	+  pageInfo: PageInfo;
616	+  onPageChange: (page: number) => void;
617	+  /** When true, the controls are hidden entirely (no items to page). */
618	+  disabled?: boolean;
619	+};
620	+
621	+function totalPages({ total, limit }: PageInfo): number {
622	+  if (limit <= 0 || total <= 0) return 1;
623	+  return Math.max(1, Math.ceil(total / limit));
624	+}
625	+
626	+function displayRange(info: PageInfo): { from: number; to: number } {
627	+  const from = totalPages(info) === 0 ? 0 : (info.page - 1) * info.limit + 1;
628	+  const to = Math.min(info.page * info.limit, info.total);
629	+  return { from, to };
630	+}
631	+
632	+export function PaginationControls({
633	+  pageInfo,
634	+  onPageChange,
635	+  disabled = false,
636	+}: PaginationControlsProps) {
637	+  const pages = totalPages(pageInfo);
638	+  const { from, to } = displayRange(pageInfo);
639	+
640	+  if (disabled || pageInfo.total === 0) return null;
641	+
642	+  const atFirst = pageInfo.page <= 1;
643	+  const atLast = pageInfo.page >= pages;
644	+
645	+  return (
646	+    <div
647	+      className="flex shrink-0 items-center justify-between border-t border-border bg-surface px-4 py-2"
648	+      role="navigation"
649	+      aria-label="Pagination"
650	+    >
651	+      <p className="text-xs text-text-muted">
652	+        <span className="font-medium text-text-secondary">
653	+          {from}&ndash;{to}
654	+        </span>{" "}
655	+        of{" "}
656	+        <span className="font-medium text-text-secondary">{pageInfo.total}</span>
657	+      </p>
658	+
659	+      <div className="flex items-center gap-1">
660	+        <span className="text-xs text-text-muted">
661	+          Page {pageInfo.page} of {pages}
662	+        </span>
663	+
664	+        <button
665	+          type="button"
666	+          onClick={() => onPageChange(pageInfo.page - 1)}
667	+          disabled={atFirst}
668	+          aria-label="Previous page"
669	+          className="flex h-7 w-7 items-center justify-center border border-border bg-surface text-text-secondary transition-colors hover:bg-surface-subtle disabled:cursor-not-allowed disabled:opacity-40"
670	+        >
671	+          <ChevronLeft className="h-3.5 w-3.5" aria-hidden="true" />
672	+        </button>
673	+
674	+        <button
675	+          type="button"
676	+          onClick={() => onPageChange(pageInfo.page + 1)}
677	+          disabled={atLast}
678	+          aria-label="Next page"
679	+          className="flex h-7 w-7 items-center justify-center border border-border bg-surface text-text-secondary transition-colors hover:bg-surface-subtle disabled:cursor-not-allowed disabled:opacity-40"
680	+        >
681	+          <ChevronRight className="h-3.5 w-3.5" aria-hidden="true" />
682	+        </button>
683	+      </div>
684	+    </div>
685	+  );
686	+}
