const handleSetFeatureActiveFilters = useCallback(
  (filters: FeatureActiveFilters) => {
    saveFeatureStatusFilter(filters.statuses);
    setFeatureActiveFiltersState(filters);
    // Reset page on filter change
    setFeaturePageState(1);
  },
  [],
);

// Reset page on search query or filter change (debounced via deferred value)
const prevDeferredTaskQuery = useRef(deferredTaskSearchQuery);
const prevTaskFilterStatuses = useRef(taskActiveFilters.statuses);
useEffect(() => {
  if (
    prevDeferredTaskQuery.current !== deferredTaskSearchQuery ||
    prevTaskFilterStatuses.current !== taskActiveFilters.statuses
  ) {
    prevDeferredTaskQuery.current = deferredTaskSearchQuery;
    prevTaskFilterStatuses.current = taskActiveFilters.statuses;
    setTaskPageState(1);
  }
}, [deferredTaskSearchQuery, taskActiveFilters]);

const prevDeferredFeatureQuery = useRef(deferredFeatureSearchQuery);
const prevFeatureFilterStatuses = useRef(featureActiveFilters.statuses);
useEffect(() => {
  if (
    prevDeferredFeatureQuery.current !== deferredFeatureSearchQuery ||
    prevFeatureFilterStatuses.current !== featureActiveFilters.statuses
  ) {
    prevDeferredFeatureQuery.current = deferredFeatureSearchQuery;
    prevFeatureFilterStatuses.current = featureActiveFilters.statuses;
    setFeaturePageState(1);
  }
}, [deferredFeatureSearchQuery, featureActiveFilters]);

const setFeaturePage = useCallback((page: number) => {
  setFeaturePageState(page);
}, []);

const setTaskPage = useCallback((page: number) => {
  setTaskPageState(page);
}, []);

const syncBoard = useCallback(() => {
  syncCurrentWorkspace().catch(() => {
    // error captured in syncError
  });
}, [syncCurrentWorkspace]);

const openTaskTab = useCallback(
  (task: ParsedTask) => {
    if (!task.backendId) return;
    wsOpenTaskTab({
      taskId: task.backendId,
      taskName: task.id,
      title: task.title,
      featureId: task.featureBackendId,
    });
  },
  [wsOpenTaskTab],
);

const openTaskTabNewSession = useCallback(
  (task: ParsedTask) => {
    if (!task.backendId) return;
    wsOpenTaskTab(
      {
        taskId: task.backendId,
        taskName: task.id,
        title: task.title,
        featureId: task.featureBackendId,
      },
      { forceNewSession: true },
    );
  },
  [wsOpenTaskTab],
);
